-- Banco inicial de Gira y Aprende: 150 preguntas (historia_jmv 25, vicenciana 25, maria 25, biblia 25, iglesia 25, santos_mision 25).
-- Idempotente (lo ejecuta jmv-ops.sh deploy): se insertan una sola vez por su id fijo.
-- Lo que el equipo de formación edite, rechace o elimine en el admin no se pisa.
-- Las categorías no son una tabla: son los 6 valores de "category" que entiende la app
-- (biblia, maria, vicenciana, historia_jmv, iglesia, santos_mision).
-- Fuentes: Manual de JMV (José Manuel Yungaicela, 2015), Sagrada Escritura,
-- Catecismo de la Iglesia Católica y documentos de la Iglesia.

INSERT INTO "game_questions" ("id", "category", "levels", "difficulty", "prompt", "options", "correctIndex", "explanation", "source") VALUES
  ('f0a1c005-0000-4000-8000-000000000001', 'historia_jmv', '["infancia","prejuvenil","juvenil"]', 1, '¿Qué significan las siglas JMV?',
